\label{th:solution_costate_u}
    Consider the system \prettyref{eq:system} together with the OCP \prettyref{eq:opt_problem}, with the cost functional \prettyref{eq:cost_functional} and the associated terminal and running costs \prettyref{eq:terminal_cost} and \prettyref{eq:running_cost}. The components of the costate $\lambda \in \mathcal{T}^*(\mathcal{M})$ on the singular arc are given by
    \begin{align*}
        \lambda_k = -e^i\bar{Q}_{ij}\partial_{x^k}\varphi^j = \dot{e}^iM_{ij}\partial_{x^k}\varphi^j \,
    \end{align*}
    with $Q_{ij} = \bar{Q}_{il}M^{lm}\bar{Q}_{mj}$.

The proof is split into three steps. First, the stationary conditions \prettyref{eq:opt_u1_stat}, \prettyref{eq:opt_u2_stat} and the consistency condition \prettyref{eq:consistency_condition} are used to identify the costate. Second, the ansatz \prettyref{eq:lambda_ansatz} is inserted into the costate differential equation \prettyref{eq:costate_diff} and the boundary condition \prettyref{eq:boundary_cond}. Third, the special choice $r_j=e^i\bar{Q}_{ij}$ is shown to satisfy the resulting relations under the condition 
$ Q_{ij} = \bar{Q}_{il}M^{lm}\bar{Q}_{mj} $. From the stationary conditions \prettyref{eq:opt_u1_stat}, \prettyref{eq:opt_u2_stat} and the consistency condition derived in \prettyref{eq:consistency_condition}, it follows that the costate $\lambda $ must satisfy
\begin{align}
    \lambda_kg^k_2 &= 0 \label{eq:xi2}\\
    (\lambda_k - \dot{e}^iM_{ij}\partial_{x^k}\varphi^j)g^k_1 &= 0 \label{eq:xi1}\\
    (\lambda_k - \dot{e}^iM_{ij}\partial_{x^k}\varphi^j)[g_1,g_2]^k &= 0 \label{eq:xi2_dot}\,.
\end{align}
Decomposing the costate as $\lambda_k =\dot{e}^iM_{ij}\partial_{x^{k}}\varphi ^{j}+c_k$ and substituting into the optimality conditions, it follows that the residual co-vector $c \in \mathcal{T}^*(\mathcal{M})$ must satisfy $c_k g^k_1  = 0, \,  c_kg^k_2 = 0, \,  c_k [g_1, g_2]^k = 0$.
Since $c$ annihilates the basis of $\mathcal{T}(\mathcal{M})$ it follows that $c=0$ identically and therefore, $\lambda_k =\dot{e}^iM_{ij}\partial_{x^{k}}\varphi ^{j}$. In particular, the costate lies in the span of the differentials of the flat output, i.e. $\lambda \in \mathrm{span}\{\mathop{}\!\mathrm{d} \varphi^1, \mathop{}\!\mathrm{d} \varphi^2\}$, which represents the first part of the proof. 

In the second part, the ansatz \prettyref{eq:lambda_ansatz} is inserted into the costate differential equation \prettyref{eq:costate_diff} and boundary condition \prettyref{eq:boundary_cond} in order to characterize the coefficient $r_j$. To verify that the ansatz satisfies the costate differential equation, \prettyref{eq:lambda_ansatz} is differentiated with respect to time, yielding
\begin{equation*}
    \scalebox{0.92}{\mbox{\ensuremath{\displaystyle 
    \begin{aligned}
            \dot{{\lambda}}_k &= -\dot{r}_j\partial_{x^k}\varphi^j - r_j\partial_{x^l}\partial_{x^k}\varphi^jg^l_au^a \\
            &= e^iQ_{ij}\partial_{x^k}\varphi^j +  \dot{e}^iM_{ij}\partial_{x^k}\mathrm{L}_{{g}_1}\varphi^ju^1 + r_j\partial_{x^l}\varphi^j\partial_{x^k}g^l_au^a \,.
    \end{aligned}
    }}}
\end{equation*}
By the use of the identity $\partial_{x^l}\varphi^j\partial_{x^k}g^l_a  = \partial_{x^k}\mathrm{L}_{g_a}\varphi^j - \partial_{x^k}\partial_{x^l}\varphi^jg^l_a$ and
Schwarz’s Theorem it follows that 
\begin{align} \label{eq:inserted_ansatz}
    \scalebox{0.9}{\mbox{\ensuremath{\displaystyle \Big[e^iQ_{ij} + \dot{r}_j\Big]\partial_{x^k}\varphi^j + \big[r_j  + \dot{e}^iM_{ij}\big]\partial_{x^k}\mathrm{L}_{g_1}\varphi^ju^1 \overset{!}{=}0}}}\,,
\end{align} has to be met. To prove that all optimality conditions are satisfied, it must be shown that the boundary condition \prettyref{eq:boundary_cond} holds. Inserting the ansatz \prettyref{eq:lambda_ansatz} into \prettyref{eq:boundary_cond}, gives 
$$-e^i\bar{Q}_{ij}\partial_{x^k}\varphi^j\big|_{t=T} = -r_j\partial_{x^k}\varphi^j\big|_{t=T}.$$

In the third step, we explicitly determine the function $r_j$.
Inserting \prettyref{eq:lambda_ansatz} into \prettyref{eq:xi1} and \prettyref{eq:xi2_dot} results in 
\begin{equation}\label{eq:opt_inserted_ansatz}
    \begin{aligned} 
    -(r_j + \dot{e}^iM_{ij})\mathrm{L}_{g_1}\varphi^j &= 0 \\
    -(r_j + \dot{e}^iM_{ij})\mathrm{L}_{[g_1,g_2]}\varphi^j &= 0 \,.
\end{aligned}
\end{equation}
Hence, from \prettyref{eq:opt_inserted_ansatz} together with \prettyref{eq:non_deg}, it follows that
\begin{align} \label{eq:r_arc}
    r_j = -\dot{e}^iM_{ij}\,.
\end{align}
Due to \prettyref{eq:r_arc}, the second term in \prettyref{eq:inserted_ansatz} vanishes. Thus, the coefficient in the ansatz \prettyref{eq:lambda_ansatz} must satisfy 
\begin{align}
    \dot{r}_j = -e^iQ_{ij} \,, \quad r_j\big|_{t=T} = e^i\bar{Q}_{ij}\big|_{t=T}\,.
\end{align}
A particular solution is given by
\begin{align} \label{eq:r_solution_ansatz}
    r_l = e^i\bar{Q}_{il} \,,
\end{align} 
which satisfies the terminal condition by construction. Moreover, from \prettyref{eq:r_arc} it follows that 
\begin{align} \label{eq:e_dot}
    \dot{e}^m = -r_lM^{lm} \,,
\end{align} where $M^{lm}$ is the inverse of $M_{ij}$ defined by $\delta^m_i = M_{il}M^{lm}$. Inserting \prettyref{eq:r_solution_ansatz} into \prettyref{eq:e_dot} yields $\dot{e}^m = -e^i\bar{Q}_{il}M^{lm}$.



Hence, the time derivative of \prettyref{eq:r_solution_ansatz} is given by
\begin{align} \label{eq:r_inserted}
    \dot{r}_j &= \dot{e}^m\bar{Q}_{mj} = -e^i\bar{Q}_{il}M^{lm}\bar{Q}_{mj} \,.
\end{align} Inserting \prettyref{eq:r_inserted} together with \prettyref{eq:r_arc} into \prettyref{eq:inserted_ansatz} leads to 
\begin{align*}
       e^i\Big[Q_{ij} - \bar{Q}_{il}M^{lm}\bar{Q}_{mj}\Big]\partial_{x^k}\varphi^j \overset{!}{=}0 \,,
\end{align*}
which can only hold true if $Q_{ij} = \bar{Q}_{il}M^{lm}\bar{Q}_{mj}$, or in matrix form $Q = \bar{Q}M^{-1}\bar{Q}$.
By the uniqueness of the solution to this terminal-value problem, it follows 
that~\eqref{eq:lambda_ansatz},



where $r_j=-e^i\bar{Q}_{ij} =  \dot{e}^iM_{ij}$.

\label{th:opt_solution}
Consider a system of the form 
\begin{align} \label{eq:system_th}
    \dot{x} = g_1(x)u^1 + g_2(x)u^2 \,,
\end{align}
with $\dim(x)=3$ and the OCP \prettyref{eq:opt_problem}, with the cost functional \prettyref{eq:cost_functional} and the associated terminal and running costs \prettyref{eq:terminal_cost} and \prettyref{eq:running_cost}. An optimal solution candidate is given by 
    \begin{align*}
        u^1 =
        \begin{cases}
            \operatorname{sgn}(u^1_{\text{sing}})\,u^1_{\max}, & |u^1_{\text{sing}}| \geq u^1_{\max},\\
            u^1_{\text{sing}}, & \text{otherwise}
        \end{cases}
    \end{align*}
    \begin{align*}
        u^2 =
        \begin{cases}
            \operatorname{sgn}(\dot{\xi}_2)\,u^2_{\max}, & \dot{\xi}_2 \neq 0\,,\\
            \operatorname{sgn}(u^2_{\text{sing}})\,u^2_{\max} &|u^2_{\text{sing}}| \geq u^2_{\max}\,\text{and}\, \dot{\xi}_2 = 0\\
            u^2_{\text{sing}}, & \text{otherwise,}
        \end{cases}
    \end{align*}
    with
    \begin{equation*}
    \scalebox{0.92}{\mbox{\ensuremath{\displaystyle \begin{aligned}
    u^1_{\text{sing}} &= \frac{\Big[\dot{y}_d^iM_{ij} +  e^i\bar{Q}_{ij}\Big]\mathrm{L}_{g_1}\varphi^j}{A_{11}}  \quad
    u^2_{\text{sing}} = \frac{A_{11}b_2-A_{21}b_1}{(A_{12}A_{21}-A_{11}A_{22})u^1}
    \end{aligned}}}}
    \end{equation*}
     where
    \begin{equation*}
    \scalebox{0.92}{\mbox{\ensuremath{\displaystyle \begin{aligned}
    A_{11} &= \mathrm{L}_{g_1}\varphi^iM_{ij}\mathrm{L}_{g_1}\varphi^j \qquad \qquad
    A_{12} = \mathrm{L}_{[g_1,g_2]}\varphi^iM_{ij}\mathrm{L}_{g_1}\varphi^j \\ 
    A_{21} &= \mathrm{L}_{g_1}\varphi^iM_{ij}\mathrm{L}_{[g_1,g_2]}\varphi^j \qquad \,\,
    A_{22} = \mathrm{L}_{[g_1,g_2]}\varphi^iM_{ij}\mathrm{L}_{[g_1,g_2]}\varphi^j \\
    b_1 &= ((\ddot{y}_d^i - \mathrm{L}_{g_1}^2\varphi^i(u^1)^2)M_{ij} - e^iQ_{ij})\mathrm{L}_{g_1}\varphi^j\\
    b_2 &= ((\ddot{y}_d^i - \mathrm{L}_{g_1}^2\varphi^i(u^1)^2)M_{ij} - e^iQ_{ij})\mathrm{L}_{[g_1,g_2]}\varphi^j\,
    \end{aligned}}}}
    \end{equation*}
    and $Q_{ij} = \bar{Q}_{il}M^{lm}\bar{Q}_{mj}$ providing $u^1 \neq 0$, and \prettyref{eq:system_th} is $x$-flat.
